    let mut started_at: Vec<Option<StdInstant>> = (0..calls.len()).map(|_| None).collect();
    let mut in_flight: FuturesUnordered<BoxFuture<'_, (usize, ToolResult)>> =
        FuturesUnordered::new();
    let mut next = 0usize;
    let mut deadline_expired = false;

    while next < calls.len() || !in_flight.is_empty() {
        while next < calls.len()
            && in_flight.len() < concurrency
            && !deadline.is_some_and(|deadline| Instant::now() >= deadline)
        {
            let idx = next;
            next += 1;
            let call = &calls[idx];
            let call_started = StdInstant::now();
            started_at[idx] = Some(call_started);
            in_flight.push(Box::pin(async move {
                let res = match timeout(tool_timeout, executor.execute(call)).await {
                    Ok(r) => r,
                    Err(_) => ToolResult {
                        tool_call_id: call.id.clone(),
                        name: call.name.clone(),
                        output: format!(
